import csv, re
from datetime import datetime
from collections import Counter, defaultdict

rows=[]
with open('expenses.csv', newline='') as f:
    for r in csv.DictReader(f):
        r={k.strip():v.strip() for k,v in r.items()}
        rows.append(r)
print('rows', len(rows))
print('ids', len(set(r['id'] for r in rows)))

def parse_date(s):
    s=s.strip()
    for fmt in ('%m/%d/%Y','%Y-%m-%d','%d %b %Y','%d %B %Y'):
        try: return datetime.strptime(s,fmt).date()
        except ValueError: pass
    raise ValueError(s)

def parse_amount(s):
    s=s.strip()
    s=s.replace('USD','').replace('$','').replace(',','').strip()
    return float(s)

for r in rows:
    r['dt']=parse_date(r['date'])
    r['amt']=parse_amount(r['amount'])

# exact duplicates by all original fields
seen=set(); uniq=[]
for r in rows:
    key=tuple(r[k] for k in ('id','date','category','amount','status'))
    if key in seen:
        print('duplicate exact row:', key)
        continue
    seen.add(key); uniq.append(r)
print('unique rows', len(uniq))

oct_ok=[r for r in uniq if r['dt'].year==2026 and r['dt'].month==10 and r['status'].lower()=='ok']
print('oct ok', len(oct_ok))
for r in sorted(oct_ok,key=lambda r:(r['dt'],int(r['id']))):
    print(r['dt'], r['id'], repr(r['category']), r['amt'])
print('total', sum(r['amt'] for r in oct_ok))

catnorm={}
for r in oct_ok:
    c=r['category'].strip().lower()
    catnorm[c]=catnorm.get(c,0)+r['amt']
print('cats')
for k,v in sorted(catnorm.items()):
    print(k, v)

print('all by status/month')
for k,v in Counter((r['dt'].strftime('%Y-%m'),r['status'].lower()) for r in uniq).items(): print(k,v)
PY", "description": "Parse and aggregate expense data"}

