import csv
from datetime import datetime
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP

def parse_date(s):
    s=s.strip()
    for fmt in ('%m/%d/%Y','%Y-%m-%d','%d %b %Y','%d %B %Y'):
        try: return datetime.strptime(s,fmt).date()
        except ValueError: pass
    raise ValueError(s)

def parse_amount(s):
    return Decimal(s.strip().replace('USD','').replace('$','').replace(',','').strip())

rows=[]; seen=set()
for r in csv.DictReader(open('expenses.csv', newline='')):
    r={k.strip():v.strip() for k,v in r.items()}
    key=tuple(r[k] for k in ('id','date','category','amount','status'))
    if key in seen: continue
    seen.add(key)
    r['dt']=parse_date(r['date']); r['amt']=parse_amount(r['amount'])
    r['cat']=r['category'].strip().lower().capitalize()
    rows.append(r)

oct_ok=[r for r in rows if r['dt'].year==2026 and r['dt'].month==10 and r['status'].lower()=='ok']
oct_ok.sort(key=lambda r:(r['dt'],int(r['id'])))
total=sum(r['amt'] for r in oct_ok)
print('total', total)
print('n',len(oct_ok),'avg', total/len(oct_ok))
cats=defaultdict(list)
for r in oct_ok: cats[r['cat']].append(r)
for c,rs in sorted(cats.items(), key=lambda kv:(-sum(x['amt'] for x in kv[1]),kv[0])):
    s=sum(x['amt'] for x in rs)
    print(f'{c:10} {len(rs):2} {s:8} {(s/total*100):.1f}%')
print('largest', max(oct_ok,key=lambda r:r['amt']))
print('excluded')
for r in rows:
    if not (r['dt'].year==2026 and r['dt'].month==10 and r['status'].lower()=='ok'):
        print(r['id'],r['date'],r['category'],r['amount'],r['status'])
